export class AppError extends Error {
  constructor(code, message, status = 400) {
    super(message);
    this.name = 'AppError';
    this.code = code;
    this.status = status;
  }
}

const isRecord = value => value !== null && typeof value === 'object' && !Array.isArray(value);
const stateError = message => new AppError('INVALID_STATE', message, 500);

export function clone(value) {
  return JSON.parse(JSON.stringify(value));
}

export function requireRecord(value, message = 'JSON object required') {
  if (!isRecord(value)) throw new AppError('INVALID_INPUT', message);
  return value;
}

export function nonEmptyString(value, field) {
  if (typeof value !== 'string' || value.trim().length === 0) {
    throw new AppError('INVALID_INPUT', `${field} must be a nonempty string`);
  }
  return value;
}

function stringList(value, field) {
  if (!Array.isArray(value)) throw new AppError('INVALID_INPUT', `${field} must be an array`);
  const result = [];
  const seen = new Set();
  for (const item of value) {
    const text = nonEmptyString(item, `${field} entries`);
    if (!seen.has(text)) {
      seen.add(text);
      result.push(text);
    }
  }
  return result;
}

export function normalizeConditions(value, field = 'conditions') {
  return value === undefined ? [] : stringList(value, field);
}

export function normalizeExpiresAt(value, field = 'expires_at') {
  if (value === null) return null;
  if (!Number.isSafeInteger(value) || value < 0) {
    throw new AppError('INVALID_INPUT', `${field} must be null or a nonnegative safe integer`);
  }
  return value;
}

export function normalizeScope(input) {
  requireRecord(input);
  return {
    product_id: nonEmptyString(input.product_id, 'product_id'),
    participant_id: nonEmptyString(input.participant_id, 'participant_id')
  };
}

export function normalizeIdentity(input) {
  const scope = normalizeScope(input);
  return { ...scope, lesson_id: nonEmptyString(input.lesson_id, 'lesson_id') };
}

export function identityKey(identity) {
  return JSON.stringify([identity.product_id, identity.participant_id, identity.lesson_id]);
}

export function normalizeCreateInput(input) {
  const identity = normalizeIdentity(input);
  return {
    ...identity,
    instruction: nonEmptyString(input.instruction, 'instruction'),
    conditions: normalizeConditions(input.conditions),
    exclusions: normalizeConditions(input.exclusions, 'exclusions'),
    source_ref: nonEmptyString(input.source_ref, 'source_ref'),
    expires_at: normalizeExpiresAt(input.expires_at === undefined ? null : input.expires_at)
  };
}

function normalizeExpectedRevision(input) {
  if (!Number.isSafeInteger(input.expected_revision) || input.expected_revision < 1) {
    throw new AppError('INVALID_INPUT', 'expected_revision must be a positive safe integer');
  }
  return input.expected_revision;
}

export function normalizeReviseInput(input) {
  const identity = normalizeIdentity(input);
  const result = {
    ...identity,
    expected_revision: normalizeExpectedRevision(input),
    instruction: nonEmptyString(input.instruction, 'instruction'),
    source_ref: nonEmptyString(input.source_ref, 'source_ref')
  };
  if (Object.hasOwn(input, 'conditions')) result.conditions = stringList(input.conditions, 'conditions');
  if (Object.hasOwn(input, 'exclusions')) result.exclusions = stringList(input.exclusions, 'exclusions');
  if (Object.hasOwn(input, 'expires_at')) result.expires_at = normalizeExpiresAt(input.expires_at);
  return result;
}

export function normalizeDisableInput(input) {
  return { ...normalizeIdentity(input), expected_revision: normalizeExpectedRevision(input) };
}

export function normalizeExplainInput(input) {
  const scope = normalizeScope(input);
  if (typeof input.text !== 'string') throw new AppError('INVALID_INPUT', 'text must be a string');
  return {
    ...scope,
    text: input.text,
    invalidated_refs: normalizeConditions(input.invalidated_refs, 'invalidated_refs'),
    override_ids: normalizeConditions(input.override_ids, 'override_ids'),
    now: normalizeExpiresAt(input.now === undefined ? Date.now() : input.now, 'now')
  };
}

export function makeLesson(input) {
  const normalized = normalizeCreateInput(input);
  return { ...normalized, revision: 1, disabled: false };
}

export function makeEvent(event_id, kind, lesson) {
  return {
    event_id,
    kind,
    identity: {
      product_id: lesson.product_id,
      participant_id: lesson.participant_id,
      lesson_id: lesson.lesson_id
    },
    revision: lesson.revision,
    source_ref: lesson.source_ref
  };
}

export function assessLessons(input, lessons) {
  const request = normalizeExplainInput(input);
  const scoped = lessons
    .filter(lesson => lesson.product_id === request.product_id && lesson.participant_id === request.participant_id)
    .sort((a, b) => a.lesson_id < b.lesson_id ? -1 : a.lesson_id > b.lesson_id ? 1 : 0);
  const text = request.text.toLowerCase();
  const invalidated = new Set(request.invalidated_refs);
  const overrides = new Set(request.override_ids);
  const assessments = [];
  const items = [];

  for (const lesson of scoped) {
    const conditions = Array.isArray(lesson.conditions) ? lesson.conditions : [];
    const exclusions = Array.isArray(lesson.exclusions) ? lesson.exclusions : [];
    const expiresAt = lesson.expires_at === undefined ? null : lesson.expires_at;
    let disposition = 'applicable';
    if (lesson.disabled) disposition = 'disabled';
    else if (expiresAt !== null && request.now >= expiresAt) disposition = 'expired';
    else if (conditions.some(condition => !text.includes(condition.toLowerCase())) || exclusions.some(exclusion => text.includes(exclusion.toLowerCase()))) disposition = 'inapplicable';
    else if (invalidated.has(lesson.source_ref)) disposition = 'unsupported';
    else if (overrides.has(lesson.lesson_id)) disposition = 'overridden';

    assessments.push({ lesson_id: lesson.lesson_id, revision: lesson.revision, disposition });
    if (disposition === 'applicable') {
      items.push({ lesson_id: lesson.lesson_id, instruction: lesson.instruction, revision: lesson.revision, source_ref: lesson.source_ref });
    }
  }
  return { items, assessments };
}

export function validateState(state) {
  if (!isRecord(state) || ![1, 2].includes(state.schema_version) || !Array.isArray(state.lessons) || !Array.isArray(state.events)) {
    throw stateError('store schema is invalid');
  }
  try {
    const identities = new Set();
    const lessonsByIdentity = new Map();
    for (const lesson of state.lessons) {
      if (!isRecord(lesson)) throw stateError('lesson record is invalid');
      const identity = normalizeIdentity(lesson);
      const key = identityKey(identity);
      if (identities.has(key)) throw stateError('duplicate lesson identity');
      identities.add(key);
      lessonsByIdentity.set(key, lesson);
      nonEmptyString(lesson.instruction, 'instruction');
      nonEmptyString(lesson.source_ref, 'source_ref');
      stringList(lesson.conditions, 'conditions');
      stringList(lesson.exclusions, 'exclusions');
      if (state.schema_version === 2 && !Object.hasOwn(lesson, 'expires_at')) throw stateError('lesson expiry is missing');
      if (Object.hasOwn(lesson, 'expires_at')) normalizeExpiresAt(lesson.expires_at);
      if (!Number.isSafeInteger(lesson.revision) || lesson.revision < 1 || typeof lesson.disabled !== 'boolean') throw stateError('lesson revision or disabled flag is invalid');
    }

    let previous = 0;
    for (const event of state.events) {
      if (!isRecord(event) || !Number.isSafeInteger(event.event_id) || event.event_id < 1 || event.event_id <= previous) throw stateError('event sequence is invalid');
      previous = event.event_id;
      if (!['created', 'revised', 'disabled'].includes(event.kind)) throw stateError('event kind is invalid');
      const identity = normalizeIdentity(event.identity);
      const lesson = lessonsByIdentity.get(identityKey(identity));
      if (!lesson) throw stateError('event refers to an unknown lesson');
      if (!Number.isSafeInteger(event.revision) || event.revision < 1 || event.revision > lesson.revision) throw stateError('event revision is invalid');
      nonEmptyString(event.source_ref, 'source_ref');
    }
  } catch (error) {
    if (error instanceof AppError && error.code === 'INVALID_STATE') throw error;
    throw stateError('store contents are invalid');
  }
  return state;
}

