    assert.equal(store.disable({ ...base('one'), expected_revision: 2 }).disabled, true);
    assert.deepEqual(store.history({ ...base('one') }).map(event => [event.event_id, event.kind, event.revision]), [[1, 'created', 1], [2, 'revised', 2], [3, 'disabled', 2]]);
